package com.secman.domain

import io.micronaut.serde.annotation.Serdeable
import jakarta.persistence.*
import java.time.Instant

/**
 * A GitHub repository accessible via the configured GitHub App.
 *
 * Rows are created/updated by the repo import (`import-github-repos` CLI /
 * `import_github_repos` MCP → `POST /api/github/import`), which upserts by
 * the stable numeric [githubRepoId] (rename-safe). `criticalCount` /
 * `highCount` hold the open Dependabot alert counts from the last import;
 * the per-import history lives in [GithubRepoFindingSnapshot].
 */
@Entity
@Table(
    name = "github_repository",
    uniqueConstraints = [
        UniqueConstraint(name = "uk_github_repo_id", columnNames = ["github_repo_id"]),
        UniqueConstraint(name = "uk_github_repo_full_name", columnNames = ["full_name"])
    ],
    indexes = [
        Index(name = "idx_github_repo_owner", columnList = "owner")
    ]
)
@Serdeable
data class GithubRepository(
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    var id: Long? = null,

    /** GitHub's stable numeric repository id. */
    @Column(name = "github_repo_id", nullable = false)
    var githubRepoId: Long = 0,

    @Column(name = "name", nullable = false, length = 255)
    var name: String = "",

    /** Owner login (org or user). */
    @Column(name = "owner", nullable = false, length = 255)
    var owner: String = "",

    /** `owner/name`. */
    @Column(name = "full_name", nullable = false, length = 512)
    var fullName: String = "",

    @Column(name = "html_url", length = 1024)
    var htmlUrl: String? = null,

    /** Notification address for the 30-day alert; editable, null = unmapped. */
    @Column(name = "owner_email", length = 255)
    var ownerEmail: String? = null,

    /** Open critical Dependabot alerts as of the last import. */
    @Column(name = "critical_count", nullable = false)
    var criticalCount: Int = 0,

    /** Open high Dependabot alerts as of the last import. */
    @Column(name = "high_count", nullable = false)
    var highCount: Int = 0,

    @Column(name = "last_import_at")
    var lastImportAt: Instant? = null,

    /** Last import at which the repo had at least one open high/critical alert. */
    @Column(name = "last_high_critical_finding_at")
    var lastHighCriticalFindingAt: Instant? = null,

    @Column(name = "archived", nullable = false)
    var archived: Boolean = false,

    @Column(name = "created_at")
    var createdAt: Instant? = null,

    @Column(name = "updated_at")
    var updatedAt: Instant? = null
) {
    @PrePersist
    fun onCreate() {
        val now = Instant.now()
        createdAt = createdAt ?: now
        updatedAt = now
    }

    @PreUpdate
    fun onUpdate() {
        updatedAt = Instant.now()
    }
}
package com.secman.domain

import com.fasterxml.jackson.annotation.JsonIgnore
import com.secman.constants.VulnerabilitySources
import io.micronaut.serde.annotation.Serdeable
import jakarta.persistence.*
import jakarta.validation.constraints.NotNull
import java.time.LocalDateTime

/**
 * Vulnerability entity representing a security vulnerability discovered during a scan.
 *
 * Linked to an Asset entity via ManyToOne relationship.
 * Feature 048: Uses transactional replace pattern - each import deletes existing vulnerabilities
 * for an asset and inserts current ones, ensuring only the latest state is stored.
 *
 * @property id Unique identifier
 * @property asset Asset this vulnerability affects (required)
 * @property vulnerabilityId CVE or vulnerability identifier (e.g., "CVE-2016-2183")
 * @property cvssSeverity CVSS severity level (e.g., "High", "Critical", "Medium", "Low", "Informational")
 * @property vulnerableProductVersions Affected product/version information
 * @property daysOpen Text representation of days open at last import (e.g., "58 days") - display only, may be stale
 * @property scanTimestamp Discovery date as reported by the most recent import (refreshed each import)
 * @property firstSeenAt Earliest known detection of this (asset, CVE, product) — preserved across re-imports.
 *                       Anchor for SLA/overdue calculations and "days open" display. Falls back to scanTimestamp on first insert.
 * @property importTimestamp When this data was imported (same for all vulns in batch, for "current" query)
 * @property patchPublicationDate When a fix became available (optional, from CrowdStrike API). Prefers a
 *                                remediation/vendor release date; falls back to the CVE publication date.
 * @property cvePublishedDate When the CVE itself was disclosed (optional). Never an SLA anchor — display only.
 * @property createdAt When the record was first created in the database (auto-generated)
 */
@Entity
@Table(
    name = "vulnerability",
    indexes = [
        // Composite (asset_id, scan_timestamp): serves WHERE asset_id = ? for asset-scoped queries
        // (via MariaDB's leftmost-prefix rule) AND threshold-date overdue queries combined with
        // asset filters. Replaces the standalone idx_vulnerability_asset that was dropped in V217.
        Index(name = "idx_vulnerability_asset_scan", columnList = "asset_id,scan_timestamp"),
        Index(name = "idx_vulnerability_severity", columnList = "cvss_severity"),                  // MCP severity filter
        Index(name = "idx_vulnerability_cve", columnList = "vulnerability_id"),                    // CVE ID lookups (MCP search)
        Index(name = "idx_vulnerability_asset_cve", columnList = "asset_id,vulnerability_id"),     // Duplicate detection
        Index(name = "idx_vulnerability_scan_timestamp", columnList = "scan_timestamp"),           // Unscoped date-range filter (MCP)
        Index(name = "idx_vulnerability_import_ts", columnList = "asset_id,import_timestamp"),     // "Current vulnerabilities" DENSE_RANK PARTITION
        // Serves the admin/user "current vulnerabilities" not_excepted view:
        //   WHERE excepted = 0 ORDER BY import_timestamp DESC, asset_name ASC, vulnerability_id ASC
        // filesort-free. The Flyway DDL (V236) creates this with import_timestamp DESC — JPA @Index
        // has no direction syntax, so **Flyway is authoritative for the column direction**; this
        // annotation exists only so hbm2ddl.auto=update sees the name already present and does NOT
        // recreate an ASC-only variant. Do not "fix" the apparent mismatch. See V236 header.
        Index(name = "idx_vulnerability_excepted_sort", columnList = "excepted,import_timestamp,asset_name,vulnerability_id")
        // NOTE: idx_vulnerability_asset, idx_vulnerability_sort_order, and
        // idx_vulnerability_product were removed in V217 because they served no read path
        // (prefix-redundancy, cross-table ORDER BY filesort, disqualified LIKE patterns
        // respectively) while contributing materially to deadlock contention and write
        // amplification during concurrent CrowdStrike imports. See V217 header for the
        // full audit rationale.
    ]
)
@Serdeable
// PERFORMANCE: When Vulnerability is loaded as a lazy ManyToOne target (e.g.
// VulnerabilityExceptionRequest.vulnerability), Hibernate batches up to N proxy
// initializations into a single IN-list select instead of issuing one round-trip per
// row. Sized to match the typical request-listing page (50). Class-level placement is
// required: Hibernate 6's AttributeBinderType rejects @BatchSize on @ManyToOne fields.
// Mirrors the identical annotation on Asset.kt.
@org.hibernate.annotations.BatchSize(size = 50)
data class Vulnerability(
    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    var id: Long? = null,

    @ManyToOne(fetch = FetchType.LAZY)
    @JoinColumn(name = "asset_id", nullable = false)
    @JsonIgnore // Prevent lazy loading errors during JSON serialization
    @NotNull
    var asset: Asset,

    @Column(name = "vulnerability_id", length = 255)
    var vulnerabilityId: String? = null,

    @Column(name = "cvss_severity", length = 50)
    var cvssSeverity: String? = null,

    @Column(name = "vulnerable_product_versions", length = 512)
    var vulnerableProductVersions: String? = null,

    @Column(name = "days_open", length = 50)
    var daysOpen: String? = null,

    @Column(name = "scan_timestamp", nullable = false)
    @NotNull
    var scanTimestamp: LocalDateTime,

    @Column(name = "first_seen_at")
    var firstSeenAt: LocalDateTime? = null,

    @Column(name = "patch_publication_date")
    var patchPublicationDate: LocalDateTime? = null,

    /**
     * CVE disclosure date, as published by the CVE record itself.
     *
     * Deliberately separate from [patchPublicationDate]: that field answers "since
     * when did a fix exist" and falls back to the CVE date only when no remediation
     * date is published, while this one always means "when was the CVE disclosed".
     * Also distinct from [firstSeenAt], which is when *we* first detected it — the
     * three routinely differ by years, and conflating them is what made a 2023 CVE
     * indistinguishable from a 2025 one in the UI.
     *
     * Display and reporting only; the SLA anchor remains [firstSeenAt] (or the
     * patch date when `secman.vulnerability.use-patch-publication-date` is on).
     */
    @Column(name = "cve_published_date")
    var cvePublishedDate: LocalDateTime? = null,

    @Column(name = "import_timestamp")
    var importTimestamp: LocalDateTime? = null,

    /**
     * Provenance of this row — which importer wrote it.
     *
     * Used by `VulnerabilityRepository.deleteStaleVulnerabilitiesBySource` so the
     * CrowdStrike reconcile sweep can target only CrowdStrike-sourced rows
     * regardless of the owning asset's owner. See [VulnerabilitySources].
     * Backfilled by V213.
     */
    @Column(name = "source", nullable = false, length = 50)
    var source: String = VulnerabilitySources.UNKNOWN,

    /**
     * Precomputed exception status — true iff a currently-active [VulnerabilityException] matches
     * this (vulnerability, asset). Replaces the per-row correlated `NOT EXISTS(EXCEPTION_MATCH)` on
     * the hot admin "current vulnerabilities" query with a sargable `WHERE excepted = 0`.
     *
     * Maintained write-time (never trust it to be real-time perfect): per-asset recompute at import,
     * scope-bounded recompute on exception create/update/delete, an hourly expiry sweep, and a full
     * recompute in the async refresh job — all via [com.secman.service.ExceptionMaterializationService],
     * all re-deriving from the SAME [com.secman.repository.ExceptionMatchSql.EXCEPTION_MATCH] predicate.
     * Default false = shown (the safe direction: over-showing is fine, over-hiding is not).
     */
    @Column(name = "excepted", nullable = false)
    var excepted: Boolean = false,

    /**
     * Precomputed product classification — whether [vulnerableProductVersions] names deployed
     * software or an installer payload ("Chrome Installer", "Photon Setup"). Derived from
     * [com.secman.domain.ProductClassificationRule] by
     * [com.secman.service.ProductClassificationService], never from CrowdStrike directly:
     * Spotlight exposes no path and no installer flag.
     *
     * Same safe direction as [excepted] — the default UNKNOWN is treated as visible, and only
     * an explicit INSTALLER_ARTIFACT hides a row.
     */
    @Enumerated(EnumType.STRING)
    @Column(name = "product_class", nullable = false, length = 20)
    var productClass: ProductClass = ProductClass.UNKNOWN,

    /**
     * Denormalized copy of `asset.name`, set at insert (see [onCreate]). Lets the default sort
     * `import_timestamp DESC, asset_name ASC, vulnerability_id ASC` be served single-table by
     * `idx_vulnerability_excepted_sort` without a cross-table filesort. Affects sort order only,
     * never visibility, so staleness after a bare asset rename is cosmetic (CrowdStrike rows
     * self-heal each import).
     */
    @Column(name = "asset_name", length = 255)
    var assetName: String? = null,

    @Column(name = "created_at", updatable = false)
    var createdAt: LocalDateTime? = null
) {
    @PrePersist
    fun onCreate() {
        val now = LocalDateTime.now()
        createdAt = now
        // Default importTimestamp to createdAt if not explicitly set
        if (importTimestamp == null) {
            importTimestamp = now
        }
        // Default firstSeenAt to scanTimestamp on first insert. Once set, this
        // value is preserved across re-imports by the import services to keep
        // SLA anchors stable when CrowdStrike resets `created_timestamp`.
        if (firstSeenAt == null) {
            firstSeenAt = scanTimestamp
        }
        // Denormalize the asset name for the filesort-free "current vulnerabilities" sort index.
        // `asset` is always attached at persist time (importers set it, CLI/XLSX construct with it),
        // so this is a plain field read, not a lazy fetch that could surprise. Sort-only; never
        // affects visibility — see the `assetName` field doc.
        if (assetName == null) {
            assetName = asset.name
        }
    }

    override fun toString(): String {
        return "Vulnerability(id=$id, vulnerabilityId='$vulnerabilityId', " +
                "cvssSeverity='$cvssSeverity', scanTimestamp=$scanTimestamp)"
    }

    override fun equals(other: Any?): Boolean {
        if (this === other) return true
        if (other !is Vulnerability) return false
        return id != null && id == other.id
    }

    override fun hashCode(): Int {
        return id?.hashCode() ?: 0
    }
}
package com.secman.repository

import com.secman.domain.GithubRepository
import io.micronaut.data.annotation.Query
import io.micronaut.data.annotation.Repository
import io.micronaut.data.jpa.repository.JpaRepository
import io.micronaut.data.model.Page
import io.micronaut.data.model.Pageable
import java.util.Optional

/**
 * Repository for imported GitHub repositories. The import upserts by the
 * stable numeric [GithubRepository.githubRepoId] (rename-safe), with
 * [findByFullName] as a fallback match for pre-existing rows.
 */
@Repository
interface GithubRepositoryRepository : JpaRepository<GithubRepository, Long> {

    fun findByGithubRepoId(githubRepoId: Long): Optional<GithubRepository>

    fun findByFullName(fullName: String): Optional<GithubRepository>

    fun findByFullNameContainingIgnoreCaseOrOwnerContainingIgnoreCaseOrOwnerEmailContainingIgnoreCase(
        fullName: String,
        owner: String,
        ownerEmail: String,
        pageable: Pageable
    ): Page<GithubRepository>

    fun findByOwnerIgnoreCase(owner: String): List<GithubRepository>

    fun countByOwnerIgnoreCase(owner: String): Long

    /** Repos with no notification email set yet — candidates for owner-email auto-discovery. */
    fun findByOwnerEmailIsNull(): List<GithubRepository>

    @Query("SELECT COALESCE(SUM(r.criticalCount), 0) FROM GithubRepository r")
    fun sumCriticalCount(): Long

    @Query("SELECT COALESCE(SUM(r.highCount), 0) FROM GithubRepository r")
    fun sumHighCount(): Long
}
package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.dto.mcp.McpExecutionContext

/**
 * Base interface for all MCP tools.
 * Each tool provides specific functionality accessible through the MCP protocol.
 *
 * Tools now receive an execution context that includes:
 * - API key information
 * - Delegated user information (if User Delegation is enabled)
 * - Pre-computed accessible asset IDs for row-level access control
 */
interface McpTool {
    /**
     * Unique identifier for this tool.
     */
    val name: String

    /**
     * Human-readable description of what this tool does.
     */
    val description: String

    /**
     * The type of operation this tool performs (READ, WRITE, DELETE).
     */
    val operation: McpOperation

    /**
     * JSON schema defining the expected input parameters.
     */
    val inputSchema: Map<String, Any>

    /**
     * Execute the tool with the provided arguments and execution context.
     *
     * The context provides:
     * - API key identification
     * - Delegated user info (when User Delegation is enabled)
     * - Pre-computed accessible asset IDs for access control filtering
     *
     * Tools MUST use context.canAccessAsset() or context.getFilterableAssetIds()
     * to apply row-level access control when User Delegation is active.
     *
     * @param arguments Tool-specific arguments from the MCP call
     * @param context Execution context with access control information
     * @return Result of tool execution
     */
    suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult
}

/**
 * Result of executing an MCP tool.
 */
sealed class McpToolResult {
    abstract val isError: Boolean

    data class Success(
        val content: Any,
        val metadata: Map<String, Any> = emptyMap()
    ) : McpToolResult() {
        override val isError = false
    }

    data class Error(
        val code: String,
        val message: String,
        val details: Map<String, Any> = emptyMap()
    ) : McpToolResult() {
        override val isError = true
    }

    companion object {
        fun success(content: Any, metadata: Map<String, Any> = emptyMap()) = Success(content, metadata)
        fun error(code: String, message: String, details: Map<String, Any> = emptyMap()) = Error(code, message, details)
    }
}package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.dto.WorkgroupAwsAccountDto
import com.secman.dto.mcp.McpExecutionContext
import com.secman.service.WorkgroupAwsAccountService
import jakarta.inject.Inject
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory

/**
 * MCP tool for listing AWS account assignments for a workgroup.
 *
 * ADMIN role is required via User Delegation.
 *
 * Input parameters:
 * - workgroupId (required): ID of the workgroup
 *
 * Returns:
 * - assignments: List of WorkgroupAwsAccountDto
 */
@Singleton
class ListWorkgroupAwsAccountsTool(
    @Inject private val workgroupAwsAccountService: WorkgroupAwsAccountService
) : McpTool {

    private val log = LoggerFactory.getLogger(ListWorkgroupAwsAccountsTool::class.java)

    override val name = "list_workgroup_aws_accounts"
    override val description = "List all AWS account assignments for a workgroup (ADMIN only, requires User Delegation)"
    override val operation = McpOperation.READ

    override val inputSchema = mapOf(
        "type" to "object",
        "properties" to mapOf(
            "workgroupId" to mapOf(
                "type" to "number",
                "description" to "ID of the workgroup"
            )
        ),
        "required" to listOf("workgroupId")
    )

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }

        if (!context.isAdmin) {
            return McpToolResult.error(
                "ADMIN_REQUIRED",
                "ADMIN role required to list workgroup AWS accounts"
            )
        }

        val workgroupId = (arguments["workgroupId"] as? Number)?.toLong()
            ?: return McpToolResult.error("VALIDATION_ERROR", "workgroupId is required and must be a valid number")

        try {
            val assignments = workgroupAwsAccountService.list(workgroupId)
                .map { WorkgroupAwsAccountDto.from(it) }

            log.debug(
                "MCP list_workgroup_aws_accounts: workgroupId={}, count={}, actor={}",
                workgroupId, assignments.size, context.delegatedUserEmail
            )

            return McpToolResult.success(mapOf("assignments" to assignments))

        } catch (e: IllegalArgumentException) {
            return McpToolResult.error("NOT_FOUND", e.message ?: "Workgroup not found")
        } catch (e: Exception) {
            log.error("Failed to list workgroup AWS accounts", e)
            return McpToolResult.error("EXECUTION_ERROR", "Failed to list workgroup AWS accounts: ${e.message}")
        }
    }
}
package com.secman.mcp.tools

import com.secman.dto.mcp.McpExecutionContext

/**
 * Shared guard helpers for MCP tool `execute()` preambles.
 *
 * Each returns an [McpToolResult.Error] when the precondition fails, or null when
 * execution may proceed — use as:
 *
 *     requireDelegation(context)?.let { return it }
 *
 * The error codes and messages are the exact strings the tools have always
 * returned; MCP clients and E2E scripts match on them, so never reword here and
 * always pass the caller's own `code`/`message` where the tool had one.
 */

/** Gate for tools that require User Delegation (audit trail). */
fun requireDelegation(context: McpExecutionContext): McpToolResult.Error? =
    if (!context.hasDelegation()) {
        McpToolResult.Error(
            "DELEGATION_REQUIRED",
            "User Delegation must be enabled to use this tool"
        )
    } else null

/**
 * Gate for tools restricted to specific delegated-user roles. Admin API keys
 * always pass; otherwise at least one of [roles] must be present on the
 * delegated user.
 */
fun requireAnyRole(
    context: McpExecutionContext,
    vararg roles: String,
    code: String = "FORBIDDEN",
    message: String = "Insufficient role to use this tool"
): McpToolResult.Error? =
    if (context.isAdmin || roles.any { context.delegatedUserRoles?.contains(it) == true }) {
        null
    } else {
        McpToolResult.Error(code, message)
    }

/**
 * Gate that looks **only** at the delegated user's own roles — unlike
 * [requireAnyRole] an admin API key does not bypass it, so "ADMIN" has to be
 * listed explicitly when it should grant access. Role names are compared
 * case-insensitively.
 */
fun requireAnyUserRole(
    context: McpExecutionContext,
    vararg roles: String,
    code: String = "AUTHORIZATION_ERROR",
    message: String
): McpToolResult.Error? {
    val held = context.delegatedUserRoles?.mapTo(mutableSetOf()) { it.uppercase() } ?: emptySet<String>()
    return if (roles.any { it.uppercase() in held }) null else McpToolResult.Error(code, message)
}

