    @PrePersist
    fun onCreate() {
        val now = LocalDateTime.now()
        createdAt = now
        // Default importTimestamp to createdAt if not explicitly set
        if (importTimestamp == null) {
            importTimestamp = now
        }
        // Default firstSeenAt to scanTimestamp on first insert. Once set, this
        // value is preserved across re-imports by the import services to keep
        // SLA anchors stable when CrowdStrike resets `created_timestamp`.
