package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.dto.mcp.McpExecutionContext

/**
 * Base interface for all MCP tools.
 * Each tool provides specific functionality accessible through the MCP protocol.
 *
 * Tools now receive an execution context that includes:
 * - API key information
 * - Delegated user information (if User Delegation is enabled)
 * - Pre-computed accessible asset IDs for row-level access control
 */
interface McpTool {
    /**
     * Unique identifier for this tool.
     */
    val name: String

    /**
     * Human-readable description of what this tool does.
     */
    val description: String

    /**
     * The type of operation this tool performs (READ, WRITE, DELETE).
     */
    val operation: McpOperation

    /**
     * JSON schema defining the expected input parameters.
     */
    val inputSchema: Map<String, Any>

    /**
     * Execute the tool with the provided arguments and execution context.
     *
     * The context provides:
     * - API key identification
     * - Delegated user info (when User Delegation is enabled)
     * - Pre-computed accessible asset IDs for access control filtering
     *
     * Tools MUST use context.canAccessAsset() or context.getFilterableAssetIds()
     * to apply row-level access control when User Delegation is active.
     *
     * @param arguments Tool-specific arguments from the MCP call
     * @param context Execution context with access control information
     * @return Result of tool execution
     */
    suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult
}

/**
 * Result of executing an MCP tool.
 */
sealed class McpToolResult {
    abstract val isError: Boolean

    data class Success(
        val content: Any,
        val metadata: Map<String, Any> = emptyMap()
    ) : McpToolResult() {
        override val isError = false
    }

    data class Error(
        val code: String,
        val message: String,
        val details: Map<String, Any> = emptyMap()
    ) : McpToolResult() {
        override val isError = true
    }

    companion object {
        fun success(content: Any, metadata: Map<String, Any> = emptyMap()) = Success(content, metadata)
        fun error(code: String, message: String, details: Map<String, Any> = emptyMap()) = Error(code, message, details)
    }
}package com.secman.mcp.tools

import com.secman.domain.McpOperation
import com.secman.dto.WorkgroupAwsAccountDto
import com.secman.dto.mcp.McpExecutionContext
import com.secman.service.WorkgroupAwsAccountService
import jakarta.inject.Inject
import jakarta.inject.Singleton
import org.slf4j.LoggerFactory

/**
 * MCP tool for listing AWS account assignments for a workgroup.
 *
 * ADMIN role is required via User Delegation.
 *
 * Input parameters:
 * - workgroupId (required): ID of the workgroup
 *
 * Returns:
 * - assignments: List of WorkgroupAwsAccountDto
 */
@Singleton
class ListWorkgroupAwsAccountsTool(
    @Inject private val workgroupAwsAccountService: WorkgroupAwsAccountService
) : McpTool {

    private val log = LoggerFactory.getLogger(ListWorkgroupAwsAccountsTool::class.java)

    override val name = "list_workgroup_aws_accounts"
    override val description = "List all AWS account assignments for a workgroup (ADMIN only, requires User Delegation)"
    override val operation = McpOperation.READ

    override val inputSchema = mapOf(
        "type" to "object",
        "properties" to mapOf(
            "workgroupId" to mapOf(
                "type" to "number",
                "description" to "ID of the workgroup"
            )
        ),
        "required" to listOf("workgroupId")
    )

    override suspend fun execute(arguments: Map<String, Any>, context: McpExecutionContext): McpToolResult {
        requireDelegation(context)?.let { return it }

        if (!context.isAdmin) {
            return McpToolResult.error(
                "ADMIN_REQUIRED",
                "ADMIN role required to list workgroup AWS accounts"
            )
        }

        val workgroupId = (arguments["workgroupId"] as? Number)?.toLong()
            ?: return McpToolResult.error("VALIDATION_ERROR", "workgroupId is required and must be a valid number")

        try {
            val assignments = workgroupAwsAccountService.list(workgroupId)
                .map { WorkgroupAwsAccountDto.from(it) }

            log.debug(
                "MCP list_workgroup_aws_accounts: workgroupId={}, count={}, actor={}",
                workgroupId, assignments.size, context.delegatedUserEmail
            )

            return McpToolResult.success(mapOf("assignments" to assignments))

        } catch (e: IllegalArgumentException) {
            return McpToolResult.error("NOT_FOUND", e.message ?: "Workgroup not found")
        } catch (e: Exception) {
            log.error("Failed to list workgroup AWS accounts", e)
            return McpToolResult.error("EXECUTION_ERROR", "Failed to list workgroup AWS accounts: ${e.message}")
        }
    }
}
package com.secman.mcp.tools

import com.secman.dto.mcp.McpExecutionContext

/**
 * Shared guard helpers for MCP tool `execute()` preambles.
 *
 * Each returns an [McpToolResult.Error] when the precondition fails, or null when
 * execution may proceed — use as:
 *
 *     requireDelegation(context)?.let { return it }
 *
 * The error codes and messages are the exact strings the tools have always
 * returned; MCP clients and E2E scripts match on them, so never reword here and
 * always pass the caller's own `code`/`message` where the tool had one.
 */

/** Gate for tools that require User Delegation (audit trail). */
fun requireDelegation(context: McpExecutionContext): McpToolResult.Error? =
    if (!context.hasDelegation()) {
        McpToolResult.Error(
            "DELEGATION_REQUIRED",
            "User Delegation must be enabled to use this tool"
        )
    } else null

/**
 * Gate for tools restricted to specific delegated-user roles. Admin API keys
 * always pass; otherwise at least one of [roles] must be present on the
 * delegated user.
 */
fun requireAnyRole(
    context: McpExecutionContext,
    vararg roles: String,
    code: String = "FORBIDDEN",
    message: String = "Insufficient role to use this tool"
): McpToolResult.Error? =
    if (context.isAdmin || roles.any { context.delegatedUserRoles?.contains(it) == true }) {
        null
    } else {
        McpToolResult.Error(code, message)
    }

/**
 * Gate that looks **only** at the delegated user's own roles — unlike
 * [requireAnyRole] an admin API key does not bypass it, so "ADMIN" has to be
 * listed explicitly when it should grant access. Role names are compared
 * case-insensitively.
 */
fun requireAnyUserRole(
    context: McpExecutionContext,
    vararg roles: String,
    code: String = "AUTHORIZATION_ERROR",
    message: String
): McpToolResult.Error? {
    val held = context.delegatedUserRoles?.mapTo(mutableSetOf()) { it.uppercase() } ?: emptySet<String>()
    return if (roles.any { it.uppercase() in held }) null else McpToolResult.Error(code, message)
}

