    fun deactivate(): GithubAppConfig = copy(isActive = false)

    fun validate(): List<String> {
        val errors = mutableListOf<String>()
        if (appId.isBlank()) {
            errors.add("App ID cannot be empty")
        } else if (!appId.all { it.isDigit() }) {
