        }
        if (privateKeyPem.isBlank()) {
            errors.add("Private key cannot be empty")
        } else if (!privateKeyPem.contains("PRIVATE KEY")) {
            errors.add("Private key must be a PEM-encoded RSA key (BEGIN [RSA] PRIVATE KEY)")
        }
