package com.secman.service

import com.fasterxml.jackson.databind.ObjectMapper
import com.secman.dto.*
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import jakarta.inject.Singleton
import java.io.ByteArrayInputStream
import java.io.ByteArrayOutputStream
import java.net.URI
import java.nio.charset.CodingErrorAction
import java.security.MessageDigest
import java.time.Instant
import java.util.Base64
import javax.imageio.ImageIO

data class ValidatedIntegrationAttachment(val fileName: String, val contentType: String, val bytes: ByteArray)
data class ValidatedIntegrationRun(val request: IntegrationRunRequest, val digest: String, val findingsJson: String, val attachments: List<List<ValidatedIntegrationAttachment>>)

object IntegrationLifecycle {
    fun resolvesAbsent(run: IntegrationRunRequest) = run.status == "SUCCESS" && run.completeCoverage
    fun isNewer(run: IntegrationRunRequest, lastScanAt: Instant?) = lastScanAt == null || run.completedAt > lastScanAt
}

@Singleton
class IntegrationRunValidator(private val mapper: ObjectMapper) {
    companion object {
        val STATUSES = setOf("SUCCESS", "PARTIAL", "FAILED", "SKIPPED")
        val SEVERITIES = setOf("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO")
        val SOURCES = setOf("GITHUB_AI", "VISUAL")
        const val MAX_ATTACHMENT_BYTES = 1024 * 1024
        const val MAX_RUN_BYTES = 5 * MAX_ATTACHMENT_BYTES
    }

    fun validate(request: IntegrationRunRequest, now: Instant = Instant.now()): ValidatedIntegrationRun {
        check(request.scannerId > 0 && request.subjectId > 0, "Invalid scanner or subject")
        text(request.runKey, 128, true)
        check(request.runKey.matches(Regex("[A-Za-z0-9._:/-]+")), "Invalid run key")
        check(request.status in STATUSES, "Invalid status")
        check(request.startedAt >= Instant.parse("2000-01-01T00:00:00Z") &&
            request.startedAt <= request.completedAt && request.completedAt <= now.plusSeconds(300), "Invalid timestamps")
        check(request.findings.size <= 500, "At most 500 findings are allowed")
        check(request.findings.map { it.externalId }.toSet().size == request.findings.size, "Duplicate external IDs")
        text(request.metadataJson, 16000)
        check(parseJson(request.metadataJson).isObject, "metadataJson must be an object")
        var total = 0L
        val attachments = request.findings.map { finding ->
            validateFinding(finding)
            total += listOfNotNull(finding.description, finding.recommendation, finding.evidence).sumOf { it.toByteArray().size.toLong() }
            finding.attachments.map {
                val attachment = validateAttachment(it)
                total += attachment.bytes.size
                check(total <= MAX_RUN_BYTES, "Evidence exceeds 5 MiB")
                attachment
            }
        }
        check(total <= MAX_RUN_BYTES, "Evidence exceeds 5 MiB")
        // Hash the fixed DTO representation, so HTTP and MCP retries share a digest.
        val digest = MessageDigest.getInstance("SHA-256").digest(mapper.writeValueAsBytes(request))
            .joinToString("") { "%02x".format(it) }
        return ValidatedIntegrationRun(request, digest,
            mapper.writeValueAsString(request.findings.map { it.copy(attachments = emptyList()) }), attachments)
    }

    private fun validateFinding(f: IntegrationFindingInput) {
        text(f.externalId, 200, true)
        check(f.severity in SEVERITIES, "Invalid severity")
        text(f.title, 500, true)
        listOf(f.description, f.recommendation, f.evidence).forEach { text(it, 16000) }
        text(f.filePath, 1024); text(f.lineRange, 100); text(f.engine, 100); text(f.model, 200)
        text(f.commitSha, 64)
        listOf(f.url, f.issueUrl, f.fixPrUrl).forEach { url ->
            text(url, 2048)
            if (url != null) {
                val uri = try { URI(url) } catch (_: Exception) { invalid("Invalid URL") }
                check(uri.scheme in setOf("https", "http") && !uri.host.isNullOrBlank() && uri.userInfo == null, "Invalid URL")
            }
        }
        check(f.confidence == null || (f.confidence.isFinite() && f.confidence in 0.0..1.0), "Invalid confidence")
        check(f.legacyIds.size <= 10 && f.legacyIds.toSet().size == f.legacyIds.size, "Invalid legacy IDs")
        f.legacyIds.forEach { text(it, 255, true) }
        check(f.attachments.size <= 10, "At most 10 attachments per finding")
    }

    private fun validateAttachment(input: IntegrationAttachmentInput): ValidatedIntegrationAttachment {
        text(input.fileName, 200, true)
        check(input.fileName.matches(Regex("[A-Za-z0-9][A-Za-z0-9._ -]*")) && !input.fileName.contains(".."), "Invalid file name")
        val extensions = mapOf("image/png" to setOf("png"), "image/jpeg" to setOf("jpg", "jpeg"),
            "text/plain" to setOf("txt"), "application/json" to setOf("json"))
        check(input.fileName.substringAfterLast('.').lowercase() in (extensions[input.contentType] ?: emptySet()), "Invalid attachment type")
        check(input.base64.length <= ((MAX_ATTACHMENT_BYTES + 2) / 3) * 4, "Attachment exceeds 1 MiB")
        val bytes = try { Base64.getDecoder().decode(input.base64) } catch (_: IllegalArgumentException) { invalid("Invalid base64") }
        check(bytes.isNotEmpty() && bytes.size <= MAX_ATTACHMENT_BYTES, "Invalid attachment size")
        val safeBytes = if (input.contentType.startsWith("image/")) sanitizeImage(bytes, input.contentType) else {
            val decoded = try {
                Charsets.UTF_8.newDecoder().onMalformedInput(CodingErrorAction.REPORT).onUnmappableCharacter(CodingErrorAction.REPORT)
                    .decode(java.nio.ByteBuffer.wrap(bytes)).toString()
            } catch (_: Exception) { invalid("Attachment must be UTF-8") }
            check(decoded.none { it == '\u0000' }, "Invalid text attachment")
            if (input.contentType == "application/json") parseJson(decoded)
            bytes
        }
        check(safeBytes.size <= MAX_ATTACHMENT_BYTES, "Attachment exceeds 1 MiB after normalization")
        return ValidatedIntegrationAttachment(input.fileName, input.contentType, safeBytes)
    }

    private fun sanitizeImage(bytes: ByteArray, contentType: String): ByteArray {
        try {
            ImageIO.createImageInputStream(ByteArrayInputStream(bytes)).use { stream ->
                val readers = ImageIO.getImageReaders(stream)
                check(readers.hasNext(), "Invalid image")
                val reader = readers.next()
                try {
                    reader.input = stream
                    val format = reader.formatName.lowercase()
                    check(if (contentType == "image/png") format == "png" else format in setOf("jpeg", "jpg"), "Image type mismatch")
                    val width = reader.getWidth(0)
                    val height = reader.getHeight(0)
                    check(width in 1..8192 && height in 1..8192 && width.toLong() * height <= 16_000_000, "Image dimensions exceed limit")
                    val output = ByteArrayOutputStream()
                    check(ImageIO.write(reader.read(0), format, output), "Unsupported image")
                    return output.toByteArray()
                } finally { reader.dispose() }
            }
        } catch (e: HttpStatusException) { throw e
        } catch (_: Exception) { invalid("Invalid image") }
    }

    private fun parseJson(value: String) = try {
        mapper.readTree(value) ?: invalid("Invalid JSON")
    } catch (_: com.fasterxml.jackson.core.JsonProcessingException) { invalid("Invalid JSON") }

    private fun text(value: String?, max: Int, required: Boolean = false) {
        check(!required || !value.isNullOrBlank(), "Required text is missing")
        check(value == null || (value.length <= max && value.none { it == '\u0000' }), "Text exceeds limit or contains invalid characters")
    }
    private fun check(condition: Boolean, message: String) { if (!condition) invalid(message) }
    private fun invalid(message: String): Nothing = throw HttpStatusException(HttpStatus.BAD_REQUEST, message)
}

package com.secman.service

import com.secman.domain.*
import com.secman.dto.*
import com.secman.repository.IntegrationRepository
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import jakarta.transaction.Transactional
import org.slf4j.LoggerFactory
import java.security.MessageDigest
import java.time.LocalDateTime
import java.time.ZoneOffset

/** Validates the complete body before entering the atomic database apply. */
@Singleton
class IntegrationScanService(private val validator: IntegrationRunValidator, private val writer: IntegrationRunWriter) {
    fun submit(request: IntegrationRunRequest, authentication: Authentication): IntegrationRunAck =
        writer.apply(validator.validate(request), authentication)
}

@Singleton
open class IntegrationRunWriter(
    private val repository: IntegrationRepository,
    private val access: IntegrationAccessService,
    private val exceptions: ExceptionMaterializationService
) {
    private val log = LoggerFactory.getLogger(IntegrationRunWriter::class.java)

    @Transactional
    open fun apply(validated: ValidatedIntegrationRun, auth: Authentication): IntegrationRunAck {
        val request = validated.request
        val scanner = repository.scannerForSubmission(request.scannerId) ?: access.notFound()
        access.requireWriter(scanner, auth)
        val subject = repository.lock(IntegrationSubject::class.java, request.subjectId) ?: access.notFound()
        if (subject.scannerId != scanner.id) access.notFound()
        access.requireAsset(subject.assetId, auth)
        repository.replay(request.scannerId, request.subjectId, request.runKey)?.let {
            if (it.contentDigest != validated.digest) conflict("Run key was already used with different content")
            return ack(it, true)
        }
        if (!IntegrationLifecycle.isNewer(request, subject.lastScanAt)) conflict("A newer or simultaneous snapshot already exists")
        // Also serialize adoption across different scanners bound to the same asset.
        val asset = repository.lock(Asset::class.java, subject.assetId) ?: access.notFound()
        val run = IntegrationRun(scannerId = request.scannerId, subjectId = request.subjectId, runKey = request.runKey,
            contentDigest = validated.digest, status = request.status, completeCoverage = request.completeCoverage,
            startedAt = request.startedAt, completedAt = request.completedAt, metadataJson = request.metadataJson,
            findingsJson = validated.findingsJson, accepted = request.findings.size)
        repository.persist(run)
        request.findings.forEachIndexed { index, input ->
            observe(subject, asset, run, input, validated.attachments[index])
        }
        if (IntegrationLifecycle.resolvesAbsent(request)) {
            val present = request.findings.mapTo(hashSetOf()) { it.externalId }
            var after = 0L
            do {
                val batch = repository.openFindingPage(subject.id!!, after)
                batch.filter { it.externalId !in present }.forEach { finding ->
                    finding.state = "RESOLVED"
                    finding.resolvedAt = request.completedAt
                    val projection = finding.vulnerabilityId?.let { repository.find(Vulnerability::class.java, it) }
                    finding.vulnerabilityId = null
                    repository.flush()
                    if (projection != null) repository.remove(projection)
                    run.resolved++
                }
                after = batch.lastOrNull()?.id ?: after
            } while (batch.size == 500)
        }
        subject.lastScanAt = request.completedAt
        subject.lastStatus = request.status
        if (request.status == "SUCCESS") subject.lastSuccessfulScanAt = request.completedAt
        repository.flush()
        exceptions.recomputeForAsset(asset.id!!)
        log.info("Integration run accepted: actorId={} scannerId={} subjectId={} runId={} accepted={} resolved={}",
            scanner.serviceUserId, scanner.id, subject.id, run.id, run.accepted, run.resolved)
        return ack(run, false)
    }

    private fun observe(subject: IntegrationSubject, asset: Asset, run: IntegrationRun, input: IntegrationFindingInput,
                        attachments: List<ValidatedIntegrationAttachment>) {
        val finding = repository.finding(subject.id!!, input.externalId) ?: IntegrationFinding(
            subjectId = subject.id!!, externalId = input.externalId, firstSeenAt = run.completedAt
        )
        var projection = finding.vulnerabilityId?.let { repository.find(Vulnerability::class.java, it) }
        if (projection == null && input.legacyIds.isNotEmpty()) {
            val candidates = repository.legacyCandidates(asset.id!!, input.legacyIds)
            if (candidates.size > 1 || candidates.any { repository.projectionClaimed(it.id!!) }) conflict("Legacy finding adoption conflicts")
            projection = candidates.singleOrNull()
            projection?.let {
                val original = (it.firstSeenAt ?: it.scanTimestamp).toInstant(ZoneOffset.UTC)
                if (original < finding.firstSeenAt) finding.firstSeenAt = original
            }
        }
        val timestamp = LocalDateTime.ofInstant(run.completedAt, ZoneOffset.UTC)
        val newProjection = projection == null
        if (projection == null) projection = Vulnerability(asset = asset, scanTimestamp = timestamp)
        projection.vulnerabilityId = identifier(run.scannerId, subject.id!!, input.externalId)
        projection.source = "INTEGRATION"
        projection.cvssSeverity = when (input.severity) {
            "INFO" -> "Informational"
            else -> input.severity.lowercase().replaceFirstChar { it.uppercase() }
        }
        // The stable external ID also anchors PRODUCT-scoped exceptions across title changes.
        projection.vulnerableProductVersions = input.externalId
        projection.scanTimestamp = timestamp
        projection.firstSeenAt = LocalDateTime.ofInstant(finding.firstSeenAt, ZoneOffset.UTC)
        projection.importTimestamp = timestamp
        if (newProjection) repository.persist(projection)
        finding.vulnerabilityId = projection.id
        finding.state = "OPEN"; finding.resolvedAt = null; finding.lastSeenAt = run.completedAt
        finding.lastRunId = run.id!!
        finding.severity = input.severity; finding.title = input.title; finding.description = input.description
        finding.recommendation = input.recommendation; finding.evidence = input.evidence; finding.filePath = input.filePath
        finding.lineRange = input.lineRange; finding.url = input.url; finding.confidence = input.confidence
        finding.engine = input.engine; finding.model = input.model; finding.commitSha = input.commitSha
        finding.issueUrl = input.issueUrl; finding.fixPrUrl = input.fixPrUrl
        if (finding.id == null) repository.persist(finding)
        attachments.forEach {
            repository.persist(IntegrationAttachment(findingId = finding.id!!, runId = run.id!!,
                fileName = it.fileName, contentType = it.contentType, content = it.bytes))
        }
    }

    private fun identifier(scannerId: Long, subjectId: Long, externalId: String): String =
        "INT:$scannerId:$subjectId:" + MessageDigest.getInstance("SHA-256").digest(externalId.toByteArray())
            .joinToString("") { "%02x".format(it) }
    private fun ack(run: IntegrationRun, replayed: Boolean) =
        IntegrationRunAck(run.id!!, run.scannerId, run.subjectId, run.status, run.accepted, run.resolved, replayed)
    private fun conflict(message: String): Nothing = throw HttpStatusException(HttpStatus.CONFLICT, message)
}

package com.secman.repository

import com.secman.domain.*
import com.secman.dto.IntegrationPage
import jakarta.inject.Singleton
import jakarta.persistence.EntityManager
import jakarta.persistence.LockModeType

/** Persistence operations used inside the integration services' transactions. */
@Singleton
class IntegrationRepository(private val em: EntityManager) {
    fun <T : Any> find(type: Class<T>, id: Long): T? = em.find(type, id)
    fun <T : Any> lock(type: Class<T>, id: Long): T? = em.find(type, id, LockModeType.PESSIMISTIC_WRITE)
    fun scannerForSubmission(id: Long): IntegrationScanner? =
        em.find(IntegrationScanner::class.java, id, LockModeType.PESSIMISTIC_READ)
    fun persist(entity: Any) { em.persist(entity) }
    fun remove(entity: Any) { em.remove(entity) }
    fun flush() { em.flush() }

    fun replay(scannerId: Long, subjectId: Long, key: String): IntegrationRun? =
        em.createQuery("FROM IntegrationRun r WHERE r.scannerId = :scanner AND r.subjectId = :subject AND r.runKey = :key", IntegrationRun::class.java)
            .setParameter("scanner", scannerId).setParameter("subject", subjectId).setParameter("key", key).resultList.singleOrNull()

    fun finding(subjectId: Long, externalId: String): IntegrationFinding? =
        em.createQuery("FROM IntegrationFinding f WHERE f.subjectId = :subject AND f.externalId = :external", IntegrationFinding::class.java)
            .setParameter("subject", subjectId).setParameter("external", externalId).resultList.singleOrNull()

    fun openFindingPage(subjectId: Long, afterId: Long): List<IntegrationFinding> =
        em.createQuery("FROM IntegrationFinding f WHERE f.subjectId = :subject AND f.state = 'OPEN' AND f.id > :after ORDER BY f.id", IntegrationFinding::class.java)
            .setParameter("subject", subjectId).setParameter("after", afterId).setMaxResults(500).resultList

    fun legacyCandidates(assetId: Long, legacyIds: List<String>): List<Vulnerability> =
        if (legacyIds.isEmpty()) emptyList() else em.createQuery(
            "FROM Vulnerability v WHERE v.asset.id = :asset AND v.vulnerabilityId IN :ids AND v.source = 'CLI_MANUAL'", Vulnerability::class.java
        ).setParameter("asset", assetId).setParameter("ids", legacyIds).setMaxResults(11).resultList

    fun projectionClaimed(id: Long): Boolean = em.createQuery(
        "SELECT COUNT(f) FROM IntegrationFinding f WHERE f.vulnerabilityId = :id", Long::class.javaObjectType
    ).setParameter("id", id).singleResult > 0

    fun attachments(findingId: Long, runId: Long): List<IntegrationAttachment> = em.createQuery(
        "FROM IntegrationAttachment a WHERE a.findingId = :finding AND a.runId = :run ORDER BY a.id", IntegrationAttachment::class.java
    ).setParameter("finding", findingId).setParameter("run", runId).setMaxResults(10).resultList

    // Only service-owned JPQL fragments reach these methods; all request values are parameters.
    fun <T : Any> page(type: Class<T>, from: String, where: String, params: Map<String, Any>, page: Int, size: Int): IntegrationPage<T> {
        require(page in 0..100000 && size in 1..100) { "Invalid pagination" }
        val query = em.createQuery("SELECT x $from WHERE $where ORDER BY x.id DESC", type)
        val count = em.createQuery("SELECT COUNT(x) $from WHERE $where", Long::class.javaObjectType)
        params.forEach { (name, value) -> query.setParameter(name, value); count.setParameter(name, value) }
        val total = count.singleResult
        return IntegrationPage(query.setFirstResult(page * size).setMaxResults(size).resultList,
            total, ((total + size - 1) / size).toInt(), page, size)
    }

    fun count(from: String, where: String, params: Map<String, Any>): Long {
        val query = em.createQuery("SELECT COUNT(x) $from WHERE $where", Long::class.javaObjectType)
        params.forEach { (name, value) -> query.setParameter(name, value) }
        return query.singleResult
    }

    fun boundSubject(scannerId: Long, assetId: Long): IntegrationSubject? = em.createQuery(
        "FROM IntegrationSubject s WHERE s.scannerId = :scanner AND s.assetId = :asset", IntegrationSubject::class.java
    ).setParameter("scanner", scannerId).setParameter("asset", assetId).resultList.singleOrNull()

    fun repositorySubject(repositoryId: Long): IntegrationSubject? = em.createQuery(
        "FROM IntegrationSubject s WHERE s.githubRepositoryId = :repo ORDER BY s.id", IntegrationSubject::class.java
    ).setParameter("repo", repositoryId).setMaxResults(1).resultList.firstOrNull()

    fun legacyAssets(name: String): List<Asset> = em.createQuery(
        "FROM Asset a WHERE a.name = :name", Asset::class.java
    ).setParameter("name", name).setMaxResults(2).resultList
}

package com.secman.service

import com.secman.domain.IntegrationScanner
import com.secman.repository.UserRepository
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton

@Singleton
class IntegrationAccessService(private val assets: AssetFilterService, private val users: UserRepository) {
    fun requireAdmin(auth: Authentication) {
        if ("ADMIN" !in auth.roles) throw HttpStatusException(HttpStatus.FORBIDDEN, "Administrator required")
    }
    fun requireAsset(assetId: Long, auth: Authentication) {
        if (!assets.canAccessAsset(assetId, auth)) notFound()
    }
    fun assetIds(auth: Authentication): Set<Long> = assets.getAccessibleAssetIds(auth)
    fun requireWriter(scanner: IntegrationScanner, auth: Authentication) {
        val user = users.findByUsername(auth.name).orElse(null)
        if (!scanner.enabled || user?.id != scanner.serviceUserId) {
            throw HttpStatusException(HttpStatus.FORBIDDEN, "Scanner submission is not permitted")
        }
    }
    fun notFound(): Nothing = throw HttpStatusException(HttpStatus.NOT_FOUND, "Integration resource not found")
}

package com.secman.service

import com.secman.domain.*
import com.secman.dto.*
import com.secman.repository.IntegrationRepository
import com.secman.repository.UserRepository
import io.micronaut.http.HttpStatus
import io.micronaut.http.exceptions.HttpStatusException
import io.micronaut.security.authentication.Authentication
import jakarta.inject.Singleton
import jakarta.transaction.Transactional
import org.slf4j.LoggerFactory

@Singleton
open class IntegrationAdminService(
    private val repository: IntegrationRepository,
    private val access: IntegrationAccessService,
    private val users: UserRepository
) {
    private val log = LoggerFactory.getLogger(IntegrationAdminService::class.java)

    @Transactional
    open fun saveScanner(id: Long?, request: IntegrationScannerRequest, auth: Authentication): IntegrationScannerDto {
        access.requireAdmin(auth)
        if (request.name.isBlank() || request.name.length > 200 || request.name.any { it.isISOControl() } ||
            request.source !in IntegrationRunValidator.SOURCES || request.staleAfterHours !in 1..8760 ||
            !users.existsById(request.serviceUserId)) invalid("Invalid scanner configuration")
        val scanner = id?.let { repository.lock(IntegrationScanner::class.java, it) ?: access.notFound() } ?: IntegrationScanner()
        if (id == null && repository.count("FROM IntegrationScanner x", "1 = 1", emptyMap()) >= 100) invalid("Scanner limit reached")
        if (id != null && scanner.source != request.source) invalid("Scanner source cannot be changed")
        scanner.name = request.name; scanner.source = request.source; scanner.serviceUserId = request.serviceUserId
        scanner.staleAfterHours = request.staleAfterHours; scanner.enabled = request.enabled
        if (id == null) repository.persist(scanner)
        log.info("Integration scanner saved: actorId={} scannerId={} outcome=success", users.findByUsername(auth.name).orElseThrow().id, scanner.id)
        return scannerDto(scanner)
    }

    @Transactional
    open fun bind(scannerId: Long, request: IntegrationSubjectRequest, auth: Authentication): Long {
        access.requireAdmin(auth)
        val scanner = repository.lock(IntegrationScanner::class.java, scannerId) ?: access.notFound()
        if ((request.assetId == null) == (request.githubRepositoryId == null)) invalid("Exactly one inventory ID is required")
        val repo = request.githubRepositoryId?.let { repository.lock(GithubRepository::class.java, it) ?: access.notFound() }
        if (repo != null && scanner.source != "GITHUB_AI") invalid("GitHub subjects require a GITHUB_AI scanner")
        val asset = if (repo != null) {
            repository.repositorySubject(repo.id!!)?.let { repository.find(Asset::class.java, it.assetId) }
                ?: resolveRepositoryAsset(repo, auth)
        } else {
            access.requireAsset(request.assetId!!, auth)
            repository.lock(Asset::class.java, request.assetId) ?: access.notFound()
        }
        access.requireAsset(asset.id!!, auth)
        repository.boundSubject(scannerId, asset.id!!)?.let { existing ->
            if (existing.githubRepositoryId != repo?.id) invalid("Asset already has a different binding")
            return existing.id!!
        }
        val subject = IntegrationSubject(scannerId = scannerId, assetId = asset.id!!, githubRepositoryId = repo?.id)
        repository.persist(subject)
        log.info("Integration subject bound: scannerId={} subjectId={} assetId={} outcome=success", scannerId, subject.id, asset.id)
        return subject.id!!
    }

    private fun resolveRepositoryAsset(repo: GithubRepository, auth: Authentication): Asset {
        val legacy = repository.legacyAssets(repo.fullName)
        // A name-only legacy match is safe only on the public instance; enterprise assets need a matching URI.
        val matching = legacy.filter { it.uri == repo.htmlUrl || (repo.githubInstance == "github.com" && it.uri.isNullOrBlank()) }
        if (legacy.size == 1 && matching.size == 1) {
            access.requireAsset(matching.single().id!!, auth)
            return matching.single()
        }
        val owner = repo.ownerEmail?.let { users.findByEmailIgnoreCase(it).orElse(null)?.username }
            ?: users.findByUsername(auth.name).orElseThrow().username
        val asset = Asset(name = repo.fullName.take(255), type = "REPOSITORY", owner = owner, uri = repo.htmlUrl)
        asset.manualCreator = users.findByUsername(auth.name).orElseThrow()
        repository.persist(asset)
        return asset
    }

    private fun invalid(message: String): Nothing = throw HttpStatusException(HttpStatus.BAD_REQUEST, message)
    companion object {
        fun scannerDto(s: IntegrationScanner) = IntegrationScannerDto(s.id!!, s.name, s.source, s.serviceUserId, s.staleAfterHours, s.enabled)
    }
}

